import{_ as e,a as s,c as i,ac as t}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Java 构建模型：从 javac 到 Maven 生命周期与 Gradle 任务","description":"从一个标准库程序的编译输出解释源码、类路径、测试和打包，再对照仓库里的 Spring Maven 工程。","frontmatter":{"title":"Java 构建模型：从 javac 到 Maven 生命周期与 Gradle 任务","description":"从一个标准库程序的编译输出解释源码、类路径、测试和打包，再对照仓库里的 Spring Maven 工程。","showdocs":{"topics":[{"id":"java","title":"Java","link":"/topics/java/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","summary":"从一个标准库程序的编译输出解释源码、类路径、测试和打包，再对照仓库里的 Spring Maven 工程。","status":"active","related":[{"title":"Java 操作与命令","link":"/programming/java/plus/ecosystem/java-general-general","kind":"排错","scope":"general","audience":"general"},{"title":"JVM 线程诊断：用锁拥有者解释阻塞","link":"/programming/java/pro/review/jvm-evidence","kind":"开发实践","scope":"general","audience":"general"},{"title":"Spring排障：输入、代理、事务与冲突","link":"/programming/java/plus/troubleshooting/spring-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"Spring完整项目：带版本的任务API","link":"/programming/java/plus/practice/spring-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Spring完整项目：带版本的任务API · Spring任务API实现了哪些业务边界至Spring完整项目怎样复用同一份源码","link":"/programming/java/plus/practice/spring-application-part-01","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"Java 文件实践：用 UTF-8 学习记录生成分类汇总","link":"/programming/java/base/intermediate/foundations"},"next":{"text":"Java 操作与命令","link":"/programming/java/plus/ecosystem/java-general-general"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Java 文件实践：用 UTF-8 学习记录生成分类汇总","link":"/programming/java/base/intermediate/foundations"},"next":{"text":"Java 操作与命令","link":"/programming/java/plus/ecosystem/java-general-general"}},"headers":[],"relativePath":"programming/java/plus/subjects/build-tools.md","filePath":"programming/java/plus/subjects/build-tools.md"}'),n={name:"programming/java/plus/subjects/build-tools.md"};function r(l,a,o,d,p,c){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="java-构建模型-从-javac-到-maven-生命周期与-gradle-任务" tabindex="-1">Java 构建模型：从 javac 到 Maven 生命周期与 Gradle 任务 <a class="header-anchor" href="#java-构建模型-从-javac-到-maven-生命周期与-gradle-任务" aria-label="Permalink to &quot;Java 构建模型：从 javac 到 Maven 生命周期与 Gradle 任务&quot;">​</a></h1><p><code>javac</code> 接收源码、编译类路径和目标版本，输出类文件；<code>java</code> 使用运行类路径加载入口类和依赖。源码多了以后，工程还需要协调资源复制、依赖解析、测试和打包。Maven 用生命周期阶段和绑定的插件目标描述这些步骤，Gradle 用项目任务及其依赖关系描述它们。先知道需要哪种证据，再选择命令。</p><h2 id="classpath" tabindex="-1">从实际文件看两种类路径 <a class="header-anchor" href="#classpath" aria-label="Permalink to &quot;从实际文件看两种类路径 {#classpath}&quot;">​</a></h2><p>在 <code>examples/java/study-report</code> 目录执行下列命令。该项目只依赖 JDK 标准库，测试源码自己提供 main。</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">javac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 21</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -encoding</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UTF-8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/StudyReport.java</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/StudyReportTest.java</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> StudyReportTest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> StudyReport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sample.tsv</span></span></code></pre></div><p>第一条同时编译应用和测试；第二条从 <code>out</code> 找到测试类，预期 <code>study tests passed</code>；第三条预期依次输出 <code>go=30</code>、<code>java=30</code>。删除测试文件名、改用一个新的空输出目录后，业务仍可能编译成功，测试入口却找不到。构建产物存在与测试已执行是两个独立的判断。<code>--release 21</code> 限制可使用的 Java 语言和标准 API 目标，即使编译器来自更新的 JDK，也不能据此推断目标机器已经安装所需运行时。</p><h2 id="maven" tabindex="-1">Maven 的阶段与依赖作用域 <a class="header-anchor" href="#maven" aria-label="Permalink to &quot;Maven 的阶段与依赖作用域 {#maven}&quot;">​</a></h2><p>转到 <code>examples/java/p2-spring</code>，<code>pom.xml</code> 指定 Java 21、Spring Boot 父项目及 Web、校验、JPA 等依赖。H2 的 <code>runtime</code> 作用域允许程序运行时找到驱动；<code>spring-boot-starter-test</code> 的 <code>test</code> 作用域为测试提供库，正常应用不该依赖其中的测试类。观察依赖时应注明在看编译、测试还是运行的类路径。</p><p><code>mvn test</code> 推进默认生命周期到 test，使用项目绑定的插件运行单元测试；<code>mvn package</code> 继续到打包。<code>mvn verify</code> 再推进到校验阶段，实际是否运行额外的集成测试由 POM 的插件绑定决定。<code>mvn install</code> 会把本项目产物写入本地仓库，仅在其他本机项目需要解析这份产物等场景才有必要。验收时查看 Surefire 的测试数量及结果，避免仅凭 <code>BUILD SUCCESS</code> 把“跳过测试”误作通过。</p><h2 id="gradle" tabindex="-1">Gradle 用任务图回答相同问题 <a class="header-anchor" href="#gradle" aria-label="Permalink to &quot;Gradle 用任务图回答相同问题 {#gradle}&quot;">​</a></h2><p>在采用 Gradle Java 插件并提交 Wrapper 的项目里，可以用 <code>./gradlew tasks --all</code> 看任务，用 <code>./gradlew build --dry-run</code> 看计划顺序，用 <code>./gradlew test --tests &quot;包名.测试类&quot;</code> 选择测试。Windows PowerShell 可替换为 <code>.\\gradlew.bat</code>。<code>--dry-run</code> 不执行测试动作；真实运行时还要分清已执行、命中缓存、已是最新、跳过等结果。仓库这份 Spring 示例使用 Maven，其目录没有 Gradle Wrapper。</p><p>自测：若应用运行时报某类缺失，先检查它是否只出现在测试作用域，以及打包产物和启动类路径是否包含它。若出现“没有运行测试”，先确认测试类能被项目约定的运行器发现，再检查筛选参数。对应命令按场景收在 <a href="/programming/java/plus/ecosystem/java-general-general">Java 操作与命令</a>。<a href="https://maven.apache.org/guides/introduction/introduction-to-the-lifecycle.html" target="_blank" rel="noopener noreferrer">Maven 生命周期</a> · <a href="https://docs.gradle.org/current/userguide/java_plugin.html" target="_blank" rel="noopener noreferrer">Gradle Java 插件</a></p>`,12)])])}const v=e(n,[["render",r]]);export{h as __pageData,v as default};
